theorem _root_.Quiver.Path.comp_injective' {V : Type _} [Quiver V]
    {a b c d : V} {p₁ : Path a b} {p₂ : Path a c} {q₁ : Path b d} {q₂ : Path c d}
    (h₁ : p₁.length = p₂.length) (h₂ : p₁.comp q₁ = p₂.comp q₂) : b = c

theorem raiseIndex_index_injective {γ δ : Λ} (hγ : (γ : TypeIndex) < β) (hδ : (δ : TypeIndex) < β)
    {A : ExtendedIndex γ} {B : ExtendedIndex δ}
    (h : raiseIndex hγ A = raiseIndex hδ B) : γ = δ

theorem appearsRaised_smul {χs : Set (CodingFunction β)}
    (U : Support β) (hU : AppearsRaised hγ χs U) (ρ : Allowable β) :
    AppearsRaised hγ χs (ρ • U)

theorem decodeRaised_smul {χs : Set (CodingFunction β)}
    (U : Support β) (hU : AppearsRaised hγ χs U) (ρ : Allowable β) :
    decodeRaised hγ χs (ρ • U) (appearsRaised_smul hγ U hU ρ) = ρ • decodeRaised hγ χs U hU

theorem smul_supports {S : Support β} {t : TSet β}
    (h : Supports (Allowable β) (S : Set (Address β)) t) (ρ : Allowable β) :
    Supports (Allowable β) ((ρ • S : Support β) : Set (Address β)) (ρ • t)

theorem decode_congr {χ : CodingFunction β} {S₁ S₂ : Support β}
    {h₁ : S₁ ∈ χ} {h₂ : S₂ ∈ χ} (h : S₁ = S₂) :
    (χ.decode S₁).get h₁ = (χ.decode S₂).get h₂

theorem convert_nearLitterMap_eq {A : ExtendedIndex β} {N₁ N₂ : NearLitter}
    (h : ConvertNearLitter S T A N₁ N₂) :
    ((convert hσS hσT A).nearLitterMap N₁).get ⟨N₂, h⟩ = N₂

theorem convertAtom_mem_convertLitter_iff {A : ExtendedIndex β}
    {a a' : Atom} {N N' : NearLitter}
    (ha : ConvertAtom S T A a a') (hb : ConvertNearLitter S T A N N') :
    a' ∈ N' ↔ a ∈ N

theorem convertNearLitter_fst {A : ExtendedIndex β} {N₁ N₂ N₃ N₄ : NearLitter}
    (h₁ : ConvertNearLitter S T A N₁ N₃) (h₂ : ConvertNearLitter S T A N₂ N₄)
    (h : N₁.1 = N₂.1) : N₃.1 = N₄.1

theorem convertNearLitter_fst' {A : ExtendedIndex β} {N₁ N₂ N₃ N₄ : NearLitter}
    (h₁ : ConvertNearLitter S T A N₁ N₃) (h₂ : ConvertNearLitter S T A N₂ N₄)
    (h : N₃.1 = N₄.1) : N₁.1 = N₂.1

theorem Specifies.of_eq_inflexibleCoe {σ : Spec β} {S : Support β} {hS : S.Strong}
    (h : σ.Specifies S hS)
    {i : κ} {hi : i < σ.max} {A : ExtendedIndex β} {P : InflexibleCoePath A}
    {χ : CodingFunction P.δ} {s : κ → Set κ} {m : κ} {u : κ → Set κ}
    (hi' : σ.f i hi = SpecCondition.inflexibleCoe A P χ s m u) :
    ∃ N t, N.1 = fuzz P.hδε t ∧ S.f i (hi.trans_eq h.max_eq_max.symm) = ⟨A, inr N⟩

theorem Specifies.of_eq_inflexibleBot {σ : Spec β} {S : Support β} {hS : S.Strong}
    (h : σ.Specifies S hS)
    {i : κ} {hi : i < σ.max} {A : ExtendedIndex β} {P : InflexibleBotPath A}
    {s : Set κ} {t : κ → Set κ}
    (hi' : σ.f i hi = SpecCondition.inflexibleBot A P s t) :
    ∃ N a, N.1 = fuzz (bot_ne_coe (a := P.ε)) a ∧
      S.f i (hi.trans_eq h.max_eq_max.symm) = ⟨A, inr N⟩

theorem strongSupport_index_lt_iff {s : Set (Address β)} (hs : Small s) {i j : κ}
    (hi : i < indexMax (strongClosure_small hs)) (hj : j < indexMax (strongClosure_small hs)) :
    StrongSupportOrder ((strongSupport hs).f i hi) ((strongSupport hs).f j hj) ↔ i < j

theorem lt_of_strongSupportRel {s : Set (Address β)} (hs : Small s) {i j : κ}
    (hi : i < indexMax (strongClosure_small hs)) (hj : j < indexMax (strongClosure_small hs))
    (h : StrongSupportRel ((strongSupport hs).f i hi) ((strongSupport hs).f j hj)) : i < j

@[simp]
theorem before_carrier (S : Support β) (i : κ) (hi : i < S.max) :
    (S.before i hi).carrier = {c | ∃ j hj, j < i ∧ S.f j hj = c}

theorem leastCompIndex_mem {γ : Λ} {S : Support β} {A : Path (β : TypeIndex) γ}
    (hS : S.CanComp A) :
    leastCompIndex hS ∈ {i | ∃ hi, ∃ (c : Address γ), S.f i hi = ⟨A.comp c.1, c.2⟩}

theorem not_lt_leastCompIndex {γ : Λ} {S : Support β} {A : Path (β : TypeIndex) γ}
    (hS : S.CanComp A) (i : κ) (hi : ∃ hi, ∃ (c : Address γ), S.f i hi = ⟨A.comp c.1, c.2⟩) :
    ¬i < leastCompIndex hS

theorem compIndex_lt_max {γ : Λ} {S : Support β} {A : Path (β : TypeIndex) γ}
    (hS : S.CanComp A) {i : κ} (hi : i < S.max) :
    compIndex hS hi < S.max

theorem compIndex_eq_comp {γ : Λ} {S : Support β} {A : Path (β : TypeIndex) γ}
    (hS : S.CanComp A) {i : κ} (hi : i < S.max) :
    ∃ d : Address γ, S.f (compIndex hS hi) (compIndex_lt_max hS hi) = ⟨A.comp d.1, d.2⟩

theorem comp_eq_of_not_canComp {γ : Λ} {S : Support β} {A : Path (β : TypeIndex) γ}
    (hS : ¬S.CanComp A) :
    S.comp A = ⟨0, fun _ h => (κ_not_lt_zero _ h).elim⟩

theorem comp_max_eq_of_canComp {γ : Λ} {S : Support β} {A : Path (β : TypeIndex) γ}
    (hS : S.CanComp A) :
    (S.comp A).max = S.max

theorem comp_max_eq_of_not_canComp {γ : Λ} {S : Support β} {A : Path (β : TypeIndex) γ}
    (hS : ¬S.CanComp A) :
    (S.comp A).max = 0

theorem comp_decomp_mem {γ : Λ} {S : Support β} {A : Path (β : TypeIndex) γ}
    (hS : S.CanComp A) {i : κ} (hi : i < S.max) :
    ⟨A.comp (decomp hS hi).1, (decomp hS hi).2⟩ ∈ S

theorem comp_decomp_eq {γ : Λ} {S : Support β} {A : Path (β : TypeIndex) γ}
    (hS : S.CanComp A) {i : κ} (hi : i < S.max) {c : Address γ} (h : S.f i hi = ⟨A.comp c.1, c.2⟩) :
    decomp hS hi = c

theorem comp_f_eq' {γ : Λ} {S : Support β} {A : Path (β : TypeIndex) γ}
    {i : κ} {hi : i < (S.comp A).max} {c : Address γ}
    (hiS : (S.comp A).f i hi = c) :
    ∃ j hj, S.f j hj = ⟨A.comp c.1, c.2⟩

theorem CanComp.smul [LeLevel β] {γ : Λ} [LeLevel γ] {S : Support β} {A : Path (β : TypeIndex) γ}
    (h : S.CanComp A) (ρ : Allowable β) :
    (ρ • S).CanComp A

theorem leastCompIndex_smul [LeLevel β] {γ : Λ} [LeLevel γ] {S : Support β}
    {A : Path (β : TypeIndex) γ} (hS : S.CanComp A) (ρ : Allowable β) :
    (ρ • S).leastCompIndex (hS.smul ρ) = S.leastCompIndex hS

theorem leastComp_smul [LeLevel β] {γ : Λ} [LeLevel γ] {S : Support β}
    {A : Path (β : TypeIndex) γ} (hS : S.CanComp A) (ρ : Allowable β) :
    (ρ • S).leastComp (hS.smul ρ) = Allowable.comp A ρ • S.leastComp hS

theorem WeakSpec.Specifies.smul {W : WeakSpec β} {S : Support β}
    (h : W.Specifies S) (ρ : Allowable β) :
    W.Specifies (ρ • S)

theorem convert_nearLitterMap_eq {N₁ N₂ : NearLitter}
    (h : ConvertNearLitter S T N₁ N₂) :
    ((convert hT hST).nearLitterMap N₁).get ⟨N₂, h⟩ = N₂

theorem convertAtom_injective {a b c : Atom}
    (ha : ConvertAtom S T a c) (hb : ConvertAtom S T b c) :
    a = b

theorem convertAtom_eq {a a' : Atom} {N N' : NearLitter}
    (ha : ConvertAtom S T a a') (hN : ConvertNearLitter S T N N') :
    a' ∈ N' ↔ a ∈ N

theorem atom_mem_infoIn_iff {S : Support 0} {e : Set Atom}
    {i : κ} {hi : i < S.max} {a : Atom} (ha : ⟨zeroPath, inl a⟩ = S.f i hi) :
    i ∈ infoIn S e ↔ a ∈ e

theorem nearLitter_mem_infoIn_iff {S : Support 0} {e : Set Atom}
    {i : κ} {hi : i < S.max} {N : NearLitter} (hN : ⟨zeroPath, inr N⟩ = S.f i hi) :
    i ∈ infoIn S e ↔ (N : Set Atom) ⊆ e

theorem Symmetric.inter {s₁ s₂ : Set (TSet β)}
    (h₁ : Symmetric hβ s₁) (h₂ : Symmetric hβ s₂) :
    Symmetric hβ (s₁ ∩ s₂)

theorem Symmetric.singletonImage {s : Set (TSet γ)} (h : Symmetric hγ s) :
    Symmetric hβ {p | ∃ a b : TSet ε, op hδ hε a b ∈ s ∧
      p = op hγ hδ (.singleton hε a) (.singleton hε b)}

theorem ModelData.TSet.singletonImage_supported (t : TSet β) :
    Symmetric hβ {p | ∃ a b : TSet ε, op hδ hε a b ∈[hγ] t ∧
      p = op hγ hδ (singleton hε a) (singleton hε b)}

theorem Symmetric.insertion2 {s : Set (TSet δ)} (h : Symmetric hδ s) :
    Symmetric hβ {p | ∃ a b c : TSet ζ, op hε hζ a c ∈ s ∧
      p = op hγ hδ (.singleton hε (.singleton hζ a)) (op hε hζ b c)}

theorem ModelData.TSet.insertion2_supported (t : TSet γ) :
    Symmetric hβ {p | ∃ a b c : TSet ζ, op hε hζ a c ∈[hδ] t ∧
      p = op hγ hδ (.singleton hε (.singleton hζ a)) (op hε hζ b c)}

theorem Symmetric.insertion3 {s : Set (TSet δ)} (h : Symmetric hδ s) :
    Symmetric hβ {p | ∃ a b c : TSet ζ, op hε hζ a b ∈ s ∧
      p = op hγ hδ (.singleton hε (.singleton hζ a)) (op hε hζ b c)}

theorem ModelData.TSet.insertion3_supported (t : TSet γ) :
    Symmetric hβ {p | ∃ a b c : TSet ζ, op hε hζ a b ∈[hδ] t ∧
      p = op hγ hδ (.singleton hε (.singleton hζ a)) (op hε hζ b c)}

theorem Symmetric.typeLower' {s : Set (TSet β)} (h : Symmetric hβ s) :
    Symmetric hβ {p | ∃ a : TSet ε, (∀ b : TSet δ, op hγ hδ b (.singleton hε a) ∈ s)
      ∧ p = .singleton hγ (.singleton hδ (.singleton hε a))}

theorem ModelData.TSet.typeLower'_supported (t : TSet α) :
    Symmetric hβ {p | ∃ a : TSet ε, (∀ b : TSet δ, op hγ hδ b (.singleton hε a) ∈[hβ] t)
      ∧ p = .singleton hγ (.singleton hδ (.singleton hε a))}

theorem Symmetric.subset :
    Symmetric hβ {p | ∃ a b : TSet δ, (∀ c : TSet ε, c ∈[hε] a → c ∈[hε] b) ∧
      p = op hγ hδ a b}

theorem interferenceSupport_ne_nearLitter {S : Support α} {T : Support γ}
    {N : NearLitter} {i : κ} (hi : i < (interferenceSupport hγ S T).max) :
    ((interferenceSupport hγ S T).f i hi).value ≠ inr N

theorem interferenceSupport_eq_atom {S : Support α} {T : Support γ}
    {i : κ} (hi : i < (interferenceSupport hγ S T).max) :
    ∃ A a, (interferenceSupport hγ S T).f i hi = ⟨A, inl a⟩

theorem raiseRaise_cases' (ρ₁ ρ₂ : Allowable β) {i : κ} {hi : i < (raiseRaise hγ S T ρ₁).max}
    {A : ExtendedIndex α} {x : Atom ⊕ NearLitter}
    (h : (raiseRaise hγ S T ρ₁).f i hi = ⟨A, x⟩) :
    (raiseRaise hγ S T ρ₂).f i hi = ⟨A, x⟩ ∨
    ∃ B : ExtendedIndex β, A = raiseIndex iβ.elim B ∧
      (raiseRaise hγ S T ρ₂).f i hi = ⟨A, Allowable.toStructPerm (ρ₂ * ρ₁⁻¹) B • x⟩

theorem raiseRaise_raiseIndex (hρS : ∀ c : Address β, raise iβ.elim c ∈ S → ρ₁⁻¹ • c = ρ₂⁻¹ • c)
    {i : κ} {hi : i < (raiseRaise hγ S T ρ₁).max}
    {A : ExtendedIndex β} {x : Atom ⊕ NearLitter}
    (h : (raiseRaise hγ S T ρ₁).f i hi = ⟨raiseIndex iβ.elim A, x⟩) :
    (raiseRaise hγ S T ρ₂).f i hi =
      ⟨raiseIndex iβ.elim A, Allowable.toStructPerm (ρ₂ * ρ₁⁻¹) A • x⟩

theorem raiseRaise_atom_spec₁
    (hρ₁S : ∀ c : Address β, raise iβ.elim (ρ₁ • c) ∈ S → ρ₁ • c = ρ₂ • c)
    {i : κ} {hi : i < (raiseRaise hγ S T ρ₁).max}
    {A : ExtendedIndex α} {a₁ a₂ : Atom}
    (ha₁ : (raiseRaise hγ S T ρ₁).f i hi = ⟨A, inl a₁⟩)
    (ha₂ : (raiseRaise hγ S T ρ₂).f i hi = ⟨A, inl a₂⟩) :
    {j | ∃ hj, (raiseRaise hγ S T ρ₁).f j hj = ⟨A, inl a₁⟩} ⊆
    {j | ∃ hj, (raiseRaise hγ S T ρ₂).f j hj = ⟨A, inl a₂⟩}

theorem raiseRaise_atom_spec₂
    (hρS : ∀ c : Address β, raise iβ.elim c ∈ S → ρ₁⁻¹ • c = ρ₂⁻¹ • c)
    {i : κ} {hi : i < (raiseRaise hγ S T ρ₁).max}
    {A : ExtendedIndex α} {a₁ a₂ : Atom}
    (ha₁ : (raiseRaise hγ S T ρ₁).f i hi = ⟨A, inl a₁⟩)
    (ha₂ : (raiseRaise hγ S T ρ₂).f i hi = ⟨A, inl a₂⟩) :
    {j | ∃ hj, ∃ N, (raiseRaise hγ S T ρ₁).f j hj = ⟨A, inr N⟩ ∧ a₁ ∈ N} ⊆
    {j | ∃ hj, ∃ N, (raiseRaise hγ S T ρ₂).f j hj = ⟨A, inr N⟩ ∧ a₂ ∈ N}

theorem raiseRaise_specifies_atom_spec
    (hρS : ∀ c : Address β, raise iβ.elim c ∈ S → ρ • c = c) {σ : Spec α}
    (hσ : σ.Specifies (raiseRaise hγ S T 1) (raiseRaise_strong hS (fun c _ => by rw [one_smul])))
    (i : κ) (hi : i < (raiseRaise hγ S T ρ).max) (A : ExtendedIndex α) (a : Atom) :
    (raiseRaise hγ S T ρ).f i hi = ⟨A, inl a⟩ →
    σ.f i (hi.trans_eq hσ.max_eq_max) = SpecCondition.atom A
      {j | ∃ hj, (raiseRaise hγ S T ρ).f j hj = ⟨A, inl a⟩}
      {j | ∃ hj N, (raiseRaise hγ S T ρ).f j hj = ⟨A, inr N⟩ ∧ a ∈ N}

theorem smul_aux₁ {s : Set (TSet ⊥)}
    (h : ∀ γ : Λ, [LtLevel γ] → cloud bot_ne_coe s = (e γ : Set (TSet γ))) (γ : Λ) [LtLevel γ] :
    cloud bot_ne_coe (ρ.val ⊥ • s) = (ρ • e) γ

theorem preferenceBase_injective {a₁ a₂ : Set Atom}
    {e₁ e₂ : ∀ (γ : Λ), [LtLevel γ] → Set (TSet γ)} (he : e₁ = e₂)
    {h₁ : ∀ (γ : Λ), [LtLevel γ] → cloud bot_ne_coe a₁ = e₁ γ}
    {h₂ : ∀ (γ : Λ), [LtLevel γ] → cloud bot_ne_coe a₂ = e₂ γ}
    (h : HEq (Preference.base a₁ h₁) (Preference.base a₂ h₂)) : a₁ = a₂

theorem NewTSet.newSingleton_toStructSet
    (β : TypeIndex) [i : LtLevel β] (t : TSet β) :
    StructSet.ofCoe (NewTSet.toStructSet (newSingleton β t)) β i.elim = {toStructSet t}

theorem Tangle.support_supports_lt [i : ModelDataLt] {β : TypeIndex}
    [iβ : LtLevel β] (t : Tangle β) :
    MulAction.Supports (Allowable β) (t.support : Set (Address β)) t

theorem chooseWf_spec [hwf : IsWellOrder α r] {deny : α → Set β}
    {h : ∀ x, #{ y // r y x } + #(deny x) < #β} (x : α) :
    chooseWf deny h x ∉ {z | ∃ (y : _) (_ : r y x), chooseWf deny h y = z} ∪ deny x

theorem chooseWf_ne_of_r [_inst : IsWellOrder α r] {deny : α → Set β}
    {h : ∀ x, #{ y // r y x } + #(deny x) < #β} (x₁ x₂ : α) (hx : r x₁ x₂) :
    chooseWf deny h x₁ ≠ chooseWf deny h x₂

theorem fuzz_congr_β {hβγ : (β : TypeIndex) ≠ γ} {hβγ' : (β' : TypeIndex) ≠ γ'}
  {t : Tangle β} {t' : Tangle β'} (h : fuzz hβγ t = fuzz hβγ' t') :
  β = β'

theorem fuzz_congr_γ {hβγ : (β : TypeIndex) ≠ γ} {hβγ' : (β' : TypeIndex) ≠ γ'}
  {t : Tangle β} {t' : Tangle β'} (h : fuzz hβγ t = fuzz hβγ' t') :
  γ = γ'

@[simp]
theorem Atom.support_carrier (a : Atom) :
    Enumeration.carrier a.support = {⟨Quiver.Path.nil, Sum.inl a⟩}

@[simp]
theorem ihAction_atomMap {β : Λ} {c : Address β} {H : HypAction c}
    {B : ExtendedIndex β} {a : Atom} : (ihAction H B).atomMap a = ⟨_, fun h => H.atomImage B a h⟩

theorem Approximates.comp {β γ : TypeIndex} {π₀ : StructApprox β} {π : StructPerm β}
    (h : π₀.Approximates π) (A : Path β γ) :
    StructApprox.Approximates (π₀.comp A) (Tree.comp A π)

theorem ExactlyApproximates.comp {β γ : TypeIndex} {π₀ : StructApprox β} {π : StructPerm β}
    (h : π₀.ExactlyApproximates π) (A : Path β γ) :
    StructApprox.ExactlyApproximates (π₀.comp A) (Tree.comp A π)

theorem Approximates.symm_map_atom {π₀ : BaseApprox} {π : BasePerm}
    (hπ : π₀.Approximates π) (a : Atom) (ha : a ∈ π₀.atomPerm.domain) :
    π₀.symm • a = π⁻¹ • a

theorem Approximates.symm_map_litter {π₀ : BaseApprox} {π : BasePerm}
    (hπ : π₀.Approximates π) (L : Litter) (hL : L ∈ π₀.litterPerm.domain) :
    π₀.symm • L = π⁻¹ • L

theorem ExactlyApproximates.of_isException {π₀ : BaseApprox} {π : BasePerm}
    (hπ : π₀.ExactlyApproximates π) (a : Atom) (ha : a.1 ∈ π₀.litterPerm.domain) :
    π.IsException a → π₀ • a ∉ litterSet (π₀ • a.1) ∨ π₀.symm • a ∉ litterSet (π₀.symm • a.1)

theorem ExactlyApproximates.mem_litterSet {π₀ : BaseApprox} {π : BasePerm}
    (hπ : π₀.ExactlyApproximates π) (a : Atom) (ha : a ∉ π₀.atomPerm.domain) :
    π • a ∈ litterSet (π • a.1)

theorem ExactlyApproximates.mem_litterSet_inv {π₀ : BaseApprox} {π : BasePerm}
    (hπ : π₀.ExactlyApproximates π) (a : Atom) (ha : a ∉ π₀.atomPerm.domain) :
    π⁻¹ • a ∈ litterSet (π⁻¹ • a.1)

theorem InflexibleBot.constrains {β : Λ} {A : ExtendedIndex β} {L : Litter}
    (h : InflexibleBot A L) :
    (⟨h.path.B.cons (bot_lt_coe _), inl h.a⟩ : Address β) < ⟨A, inr L.toNearLitter⟩

@[aesop unsafe 50% apply]
theorem inflexible_of_inflexibleBot {β : Λ} {A : ExtendedIndex β} {L : Litter}
    (h : InflexibleBot A L) : Inflexible A L

@[aesop unsafe 50% apply]
theorem inflexible_of_inflexibleCoe {β : Λ} {A : ExtendedIndex β} {L : Litter}
    (h : InflexibleCoe A L) : Inflexible A L

theorem inflexible_iff_inflexibleBot_or_inflexibleCoe {β : Λ} {A : ExtendedIndex β}
    {L : Litter} :
    Inflexible A L ↔ Nonempty (InflexibleBot A L) ∨ Nonempty (InflexibleCoe A L)

theorem Flexible.smul {β : Λ} [LeLevel β] {A : ExtendedIndex β} {L : Litter}
    (h : Flexible A L) (ρ : Allowable β) :
    Flexible A (Allowable.toStructPerm ρ A • L)

theorem smul_atom_eq {hφ : φ.Lawful} {π : BasePerm}
    (hπ : (φ.complete hφ A).ExactlyApproximates π) {a : Atom} (ha : (φ.atomMap a).Dom) :
    π • a = (φ.atomMap a).get ha

theorem mappedOutsideSubset_spec (L : Litter) (hL : (φ.litterMap L).Dom) :
    φ.mappedOutsideSubset L hL ⊆ litterSet L \ φ.atomMap.Dom ∧
      #(φ.mappedOutsideSubset L hL) = #{a : Atom | φ.MappedOutside L hL a}

theorem supportedAction_eq_of_mem_preimageLitterSubset {a : Atom}
    (ha : a ∈ φ.preimageLitterSubset) :
    (φ.supportedActionAtomMapCore a).get (Or.inr (Or.inl ha)) = φ.preimageLitterEquiv ⟨a, ha⟩

theorem supportedAction_eq_of_mem_mappedOutsideSubset {a : Atom}
    {L : Litter} {hL : (litterMap φ L).Dom}
    (ha : a ∈ φ.mappedOutsideSubset L hL) :
    (φ.supportedActionAtomMapCore a).get (Or.inr (Or.inr ⟨L, hL, ha⟩)) =
      φ.mappedOutsideEquiv L hL ⟨a, ha⟩

theorem mk_dom_symmDiff_le :
    #(φ.litterMap.Dom ∆ (φ.roughLitterMapOrElse '' φ.litterMap.Dom) : Set Litter) ≤
      #{L : Litter | ¬φ.BannedLitter L}

theorem orbitSetEquiv_injective {a₁ a₂ : Sum (ℕ × φ.needBackwardImages) (ℕ × φ.needForwardImages)}
    {L₁ L₂ : Litter} (h : ((φ.orbitSetEquiv L₁).symm a₁ : Atom) = (φ.orbitSetEquiv L₂).symm a₂) :
    L₁ = L₂ ∧ a₁ = a₂

theorem orbitSetEquiv_symm_congr {L L' : Litter}
    {a : Sum (ℕ × ↥φ.needBackwardImages) (ℕ × ↥φ.needForwardImages)} (h : L = L') :
    ((φ.orbitSetEquiv L).symm a : Atom) = (φ.orbitSetEquiv L').symm a

theorem nextForwardImage_eq {L₁ L₂ : Litter} {a b : ℕ × φ.needForwardImages}
    (hL₁ : L₁ ∈ (φ.litterPerm hφ).domain) (hL₂ : L₂ ∈ (φ.litterPerm hφ).domain)
    (h : φ.nextForwardImage hφ L₁ a = φ.nextForwardImage hφ L₂ b) : L₁ = L₂

